/**
 * @distilled.cloud/sproutboat -- Sproutboat Cloud API SDK for Effect.
 *
 * `./services` is generated by `scripts/generate.ts` from the Smithy model
 * that `scripts/convert.ts` converts from the OpenAPI document mirrored at
 * `specs/spec-mirror-sproutboat/specs/openapi.yaml`. Everything else in this
 * folder is hand-written.
 *
 * Sproutboat is one service, so its operations are exported straight off the
 * package root.
 *
 * @example
 * ```ts
 * import * as Sproutboat from "@distilled.cloud/sproutboat";
 *
 * const app = yield* Sproutboat.getApp({ project: "hello-api" });
 * ```
 */
export * from "./credentials.ts";
export * from "./errors.ts";
export * as T from "./traits.ts";
export {
  SproutboatProtocol,
  type SproutboatOpError,
  type SproutboatOpContext,
} from "./protocol.ts";
export * as Retry from "./retry.ts";
export * from "./services/sproutboat.ts";
// The service-local typed error classes shadow the same-named shared ones
// from ./errors.ts -- the operations raise the service-local classes.
export { BadRequest, Conflict, Forbidden, NotFound } from "./services/sproutboat.ts";
